let clubState=null;
let clubReviewContext=null;
const clubCount=()=>db?._view?.review?.club??db?.club?.proposals.filter(p=>p.status==='pending').length??0;
function clubActionLabel(p){return ({'car.purchase':'Mark Wishlist car purchased','car.save':(p.payload?.id||p.editing)?'Update car details':'Add a car','part.save':(p.payload?.id||p.editing)?'Update inventory part':'Add an inventory part','car.delete':'Permanently delete car and return fitted stock','guide.add':'Add a manual or part guide','guide.edit':'Update guide details','guide.remove':'Remove a guide','part.deleteMany':'Delete unused catalogue entries','work.add':'Record completed work','test.add':'Record a manual test','settings.save':'Update collection preferences','build.create':'Build a new car','setup.save':'Save a setup','catalogue.apply':'Import a catalogue','submission.add':'Add cars to the import inbox'}[p.action]||p.action.split('.').map(fieldLabel).join(' · '));}
function clubFieldLabel(value){return value.split(' → ').map((v,i)=>i===1?v:fieldLabel(v)).join(' → ');}
function clubReviewIdentity(p,withPhoto=false){const c=db._view?.proposalContexts?.[p.id]||ReviewModel.proposalContext(db,p);return `<div class="club-review-identity">${withPhoto&&c.picture?`<img src="${esc(c.picture)}" alt="">`:uiTile(c.carId?'car':'share','amber')}<div><h3>${esc(c.name||clubActionLabel(p))}</h3>${c.name?`<p class="club-review-operation">${esc(clubActionLabel(p))}</p>`:''}${c.detail&&c.detail!==c.name?`<p>${esc(c.detail)}</p>`:''}${c.renamedTo?`<p>Rename to <strong>${esc(c.renamedTo)}</strong></p>`:''}</div></div>`;}
function clubReviewValue(field,value){return field.endsWith(' → carId')&&!['Not recorded','Empty',''].includes(value)?(db.cars.find(c=>c.id===value)?.name||'Car no longer in collection'):value;}
function clubBanner(){
 if(!local()||!db.club)return '';
 const c=clubState||{},outdated=c.active&&c.state!=='connected';
 return `<section class="club-banner ${outdated?'club-outdated':''}" role="status"><div><strong>${outdated?'This shared copy is '+(c.state==='outdated'?'out of date':'offline'):'Dealership Mode · shared collection'}</strong><p>${outdated?`Your copy: revision ${c.revision}. ${c.latest!=null?'Dealership: revision '+c.latest+'. ':''}Reconnect and confirm an update before saving changes.`:'Everyday edits save directly. New cars, saved setups and bulk imports go to Review.'}</p>${c.outbox?`<p>${c.outbox} change(s) saved on this computer awaiting delivery.</p>`:''}</div><div class="actions">${btn('Dealership connections','club-connections')}${btn('Review changes ('+clubCount()+')','club-review','primary')}</div></section>`;
}
function dealershipPasswordFields(){return '<p>One password for Paddock and Timing. Everyone who connects has full Dealership access. Everyday edits save directly; new cars, saved setups and bulk imports need Review.</p><label class="field">Password<input name="password" type="password" autocomplete="new-password" minlength="4" maxlength="128" required></label><label class="field">Confirm password<input name="confirm" type="password" autocomplete="new-password" minlength="4" maxlength="128" required></label><p class="tiny muted">4–128 letters, numbers, spaces or symbols. This password is saved on this computer and stays the same after restarting.</p>';}
function renderDealershipExit(){
 if(!db.club||db.club.replica||clubState?.active)return '';
 return `<div class="panel mt"><h3>Turn off Dealership Mode</h3><p class="muted">Return this collection to ordinary local use. Your cars, history and shared local library with Timing stay available.</p>${btn('Turn off Dealership Mode…','club-disable')}<p class="tiny muted">Stopping hosting only pauses network access. Turning the mode off also removes its banner and dealership review rules.</p></div>`;
}
function renderDealershipHost(c){
 const hosting=net.sharing&&net.hostingMode==='dealership';
 return '<p>'+badge(hosting?'Dealership online':'Dealership offline',hosting?'good':'')+' '+esc(db.settings.name)+'</p><p>Use this same address and password in Paddock and Timing. Connected apps can browse cars and send race results. Paddock saves everyday edits directly and reviews important collection changes.</p>'+(hosting?'<h3>Dealership address</h3>'+(net.addresses.length?net.addresses.map(a=>'<div class="code">'+esc(a)+'</div>').join(''):'<div class="code">127.0.0.1:'+net.port+'</div>'):'')+'<h3>Dealership password</h3>'+(c.password?'<div class="code">'+esc(c.password)+'</div><p class="tiny muted">Remembered on this computer. Use it again after restarting hosting.</p>':'<p>Choose your password to start hosting.</p>')+'<div class="actions">'+btn(c.password?'Change password…':'Set password…','club-password')+(hosting?btn('Stop Dealership','club-stop'):c.password?btn('Start Dealership','club-start','primary'):'')+btn('Review changes','club-review')+'</div>';
}
function renderClubConnections(){
 const c=clubState||{};
 return `<section class="panel club-connections"><div class="panel-heading"><h2>${icon('share')} Dealership Mode</h2></div><div class="panel-body"><p>Keep one collection connected across your home or club computers. The dealership computer holds the official collection, reviews proposed changes and serves Timing.</p>${c.role==='coordinator'?renderDealershipHost(c):c.active?`${dl([['Collection',c.name],['Dealership',c.address],['Status',c.state],['Local revision',String(c.revision)],['Dealership revision',c.latest==null?'Not checked':String(c.latest)]])}${c.lastError?`<p class="note">${esc(c.lastError)}</p>`:''}<div class="actions">${btn('Reconnect…','club-join')}${c.state==='outdated'?btn('Back up & update…','club-update','primary'):''}${c.outbox?btn('Retry saved changes','club-retry')+btn('Discard unsent changes…','club-discard'):''}${btn('Open personal collection','club-personal')}${btn('Disconnect from dealership…','club-leave')}</div><p class="tiny muted">This copy cannot act as a host. Use the dealership computer address in Timing. A recovery backup is kept before replacing this copy.</p>`:`<div class="actions">${!db.club?btn('Enable Dealership Mode…','club-enable','primary'):''}${btn(c.paired?'Reconnect to dealership…':'Connect to a dealership…','club-join')}${c.paired&&c.hasCopy?btn('Open saved collection copy','club-open'):''}${c.paired?btn('Disconnect from dealership…','club-leave'):''}</div>`}${c.backup?`<p class="tiny muted">Last recovery backup: ${esc(c.backup)}</p>`:''}<p class="tiny muted">Local network only. Personal collections remain separate when joining. Your Dealership password and connection are remembered on this computer. Collection copies and unsent changes are also saved.</p></div></section>`;
}
async function reloadClub(){const r=await readScreen();db=r.data;clubState=r.club;net=r.network;collectionMeta=r.collection;dataPath=r.dataPath;tableColumns=[...db.settings.columns];await initMergeReview();return r;}
function clubQueued(result){if(!result?.queued)return;clubState=result.club||clubState;const e=Error(result.message);e.clubQueued=true;throw e;}
function finishClubQueued(e){if(!e.clubQueued)return false;if($('#dialog').open)$('#dialog').close();modalSubmit=null;modalPhoto=null;workshopJob=null;carId=null;partId=null;source='local';page='Review';reviewTab='Club changes';render();toast(e.message);return true;}
function clubJoin(){const c=clubState||{};simpleForm('Connect / reconnect to a dealership',`<p>Connect to your home or club dealership from a trusted computer. The saved copy includes private ownership, stock, jobs, documents and review history. Your personal collection stays separate.</p>${field('address','Dealership address and port',c.address||'')}${field('name','This computer’s name',c.device||'')}<label class="field">Dealership password<input name="code" type="password" autocomplete="current-password" value="${esc(c.savedPassword||'')}" minlength="4" maxlength="128" required></label>`,async p=>{await api('club','join',p);switchCollection('local');await reloadClub();page='Connections';},'Connect to dealership');}
function renderClubReview(){
 if(db._view?.reviewedCount!==undefined){const history=!!db._view.request.reviewHistory,items=db.club.proposals;return `<div class="actions mb">${btn(history?'Pending changes':'Reviewed changes ('+db._view.reviewedCount+')','query-review-history')}</div>`+(history?items.map(p=>`<div class="panel list-row"><div>${clubReviewIdentity(p)}<p class="tiny muted">${esc(p.device)} · ${date(p.reviewed)}</p>${p.acceptedFields?`<p class="tiny muted">Applied: ${p.acceptedFields.map(f=>esc(clubFieldLabel(f))).join(', ')}. Other proposed fields were not applied.</p>`:''}</div>${badge(p.status,p.status==='accepted'?'good':'')}</div>`).join('')||'<p>No decisions yet.</p>':`<p class="note info">Approval rechecks the current records and stock. Open a comparison to approve or reject.</p>`+(items.map(p=>`<article class="panel club-proposal"><div>${clubReviewIdentity(p)}<p class="tiny muted">Submitted by ${esc(p.device)} · ${date(p.received)} · ${p.original.length} change(s)</p></div>${clubState?.role==='coordinator'?btn('Review comparison','club-compare','primary',p.id):badge('Awaiting review')}</article>`).join('')||empty('No pending dealership changes','Important collection changes appear here. Routine edits save directly.')));}

 const pending=db.club?.proposals.filter(p=>p.status==='pending')||[],history=db.club?.proposals.filter(p=>p.status!=='pending')||[];
 return `<p class="note info">New cars, saved setups and bulk changes require approval. Approval rechecks the current records and stock. ${clubState?.role==='coordinator'?'Open a comparison to approve or reject.':'Review decisions are made on the dealership computer.'}</p>${pending.length?`<div class="club-proposals">${pending.map(p=>`<article class="panel club-proposal"><div>${clubReviewIdentity(p)}<p class="tiny muted">Submitted by ${esc(p.device)} · ${date(p.received)} · ${p.original.length} change(s)</p></div>${clubState?.role==='coordinator'?btn('Review comparison','club-compare','primary',p.id):badge('Awaiting review')}</article>`).join('')}</div>`:empty('No pending dealership changes','Important collection changes appear here. Routine edits save directly.')}<details class="panel mt"><summary>Reviewed changes (${history.length})</summary>${history.slice(0,50).map(p=>`<div class="list-row"><div>${clubReviewIdentity(p)}<p class="tiny muted">${esc(p.device)} · ${date(p.reviewed)}</p>${p.acceptedFields?`<p class="tiny muted">Applied: ${p.acceptedFields.map(f=>esc(clubFieldLabel(f))).join(', ')}. Other proposed fields were not applied.</p>`:''}</div>${badge(p.status,p.status==='accepted'?'good':'')}</div>`).join('')||'<p>No decisions yet.</p>'}</details>`;
}
async function clubComparison(id){
 const context={id,databaseId:db.id,path:dataPath},v=await api('club','preview',{id});
 if(context.databaseId!==db.id||context.path!==dataPath)throw Error('The collection changed. Reopen Review.');
 clubReviewContext={...context,token:v.token};
 const rows=v.changes.length?v.changes:v.original,proposal=db.club.proposals.find(p=>p.id===id),details=JSON.stringify(proposal?.payload||{},(_key,value)=>typeof value==='string'&&value.startsWith('data:')?'[Image / attachment: '+value.length+' characters]':value,2);
 modal('Review · '+(v.pictureComparison?.name||ReviewModel.proposalContext(db,proposal||v).name||clubActionLabel(v)),`${clubReviewIdentity(proposal||v,true)}${v.pictureComparison?`<div class="catalogue-preview-pair"><figure><figcaption>Current picture</figcaption>${v.pictureComparison.current.picture?`<img src="${esc(v.pictureComparison.current.picture)}" alt="Current picture">`:'No picture'}</figure><figure><figcaption>Selected catalogue picture</figcaption><img src="${esc(v.pictureComparison.proposed.picture)}" alt="Proposed picture"></figure></div><p class="tiny muted catalogue-picture-source">Source: ${esc(v.pictureComparison.imageUrl)}</p>`:''}<p class="tiny muted">Submitted by ${esc(v.device)}</p>${v.conflict?'<p class="note">The official collection changed after this proposal was made. This is a fresh comparison against the current collection; nothing has been applied.</p>':''}${v.error?`<p class="note">Cannot approve: ${esc(v.error)}</p>`:''}${v.selectableFields?`<fieldset data-review-selection><legend>Choose independent fields to apply</legend>${ReviewSelection.toolbar()}${v.selectableFields.map(f=>`<label class="check-row"><input type="checkbox" data-review-choice data-club-accept-field="${esc(f)}" checked>${esc(clubFieldLabel(f))}</label>`).join('')}</fieldset>`:v.pictureComparison?'<p class="note info">Approval changes only this product’s picture and its source information. Stock and specifications stay unchanged.</p>':'<p class="note info">These dependent changes are reviewed and applied together.</p>'}<p class="tiny muted">Showing up to 200 changed fields. Review large catalogue imports in smaller batches. History timestamps and reusable suggestions are omitted.</p><div class="club-comparison"><table><thead><tr><th>Field</th><th>Original</th><th>Current</th><th>Proposed</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(clubFieldLabel(r.field))}</td><td>${esc(clubReviewValue(r.field,v.original.find(o=>o.field===r.field)?.before||'Not recorded'))}</td><td>${esc(clubReviewValue(r.field,r.before))}</td><td>${esc(clubReviewValue(r.field,r.after))}</td></tr>`).join('')}</tbody></table></div><details class="club-command"><summary>Full submitted change</summary><pre>${esc(details)}</pre></details>${v.conflict&&!v.error?'<label class="check"><input type="checkbox" name="confirmConflict" required> I have reviewed the changed collection and want to apply this proposal against its current state.</label>':''}`,v.error?null:async p=>{
   if(context.databaseId!==db.id||context.path!==dataPath)throw Error('The collection changed. Reopen Review.');
   await api('club','review',{id,token:v.token,decision:'accept',...(v.selectableFields?{fields:[...document.querySelectorAll('[data-club-accept-field]:checked')].map(e=>e.dataset.clubAcceptField)}:{}),confirmConflict:p.confirmConflict==='on'});await reloadClub();clubReviewContext=null;toast('Changes approved and saved to the official collection.');
 },'Approve changes');
 $('#dialog .dialog-footer').insertAdjacentHTML('afterbegin',btn('Reject proposal','club-reject','danger',id));$('#dialog .dialog-body').scrollTop=0;
}
async function clubAction(action,id){
 if(action==='club-reject'){
  const c=clubReviewContext;if(!c||c.id!==id||c.databaseId!==db.id||c.path!==dataPath)throw Error('The collection changed. Reopen Review.');
  await api('club','review',{id,token:c.token,decision:'reject'});await reloadClub();clubReviewContext=null;$('#dialog').close();modalSubmit=null;render();toast('Proposal rejected. The collection was not changed.');return true;
 }
 if(action==='club-connections'){switchCollection('local');page='Connections';render();return true;}
 if(action==='club-review'){switchCollection('local');page='Review';reviewTab='Club changes';render();return true;}
 if(action==='club-enable'){if(net.sharing&&net.hostingMode==='legacy'){hostMigrationDialog();return true;}simpleForm('Enable Dealership Mode',`<p>This makes <strong>${esc(db.settings.name)}</strong> the official shared collection for your home or club. Everyday edits save directly; new cars, saved setups and bulk imports go through Review. Trusted computers will receive the entire collection, including its private records. A recovery backup is created first.</p>${field('name','This computer’s name',clubState?.device||'')}${dealershipPasswordFields()}<label class="check"><input name="confirmed" type="checkbox" required> I want to share this entire collection with my trusted computers.</label>`,async p=>{if(p.password!==p.confirm)throw Error('The passwords do not match.');let error;try{await api('club','enable',{name:p.name,password:p.password});}catch(e){error=e;}await reloadClub();if(error){if(clubState.role!=='coordinator')throw error;toast('Dealership settings saved, but hosting could not start: '+error.message+' Use Start Dealership to retry.',true);}},'Enable Dealership Mode');return true;}
 if(action==='club-password'){simpleForm('Dealership password',dealershipPasswordFields(),async p=>{if(p.password!==p.confirm)throw Error('The passwords do not match.');await api('club','password',{password:p.password});await reloadClub();toast('Dealership password saved. Reconnect other apps with this password.');},'Save password');return true;}
 if(action==='club-start'||action==='club-stop'){await api('club',action==='club-start'?'start':'stop');await reloadClub();render();return true;}
 if(action==='club-disable'){
  const context={databaseId:db.id,clubId:db.club?.id,revision:db.revision,recoveryId:db._view?.token?.epoch};
  modal('Turn off Dealership Mode?',`<p>Your cars, stock, setups and racing history remain in this library. Timing and Paddock on this computer can continue using the same shared file.</p><p>Dealership network hosting stops, its banner disappears, and new local cars and setups save directly.</p><p>A full recovery backup is saved first, including dealership review history. ${clubCount()?`The ${clubCount()} pending proposal(s) will not be applied; they remain in that backup.`:'Existing dealership review history remains in that backup.'}</p><p class="tiny muted">Other computers keep their saved copies but cannot submit to this dealership. Turning the mode on again creates a new dealership connection.</p>`,async()=>{try{await api('club','disable',context);}finally{await reloadClub();}page='Connections';toast('Dealership Mode is off. Your collection is still available.');},'Back up & turn off');return true;
 }
 if(action==='club-join'){clubJoin();return true;}
 if(action==='club-personal'||action==='club-open'){await api('club','switch',{active:action==='club-open'});switchCollection('local');await reloadClub();page='Connections';render();return true;}
 if(action==='club-update'){modal('Replace this outdated collection copy?',`<p>Your copy is revision ${clubState.revision}; the dealership computer reports revision ${clubState.latest}.</p><p>A separate recovery backup will be saved before downloading the latest approved collection. Your personal collection stays unchanged.</p>${clubState.outbox?`<p class="note">${clubState.outbox} unsent proposal(s) will be preserved separately. They may conflict and still require review.</p>`:''}`,async()=>{try{await api('club','update',{revision:clubState.latest});}finally{await reloadClub();}},'Back up & update');return true;}
 if(action==='club-retry'){await api('club','retry');await reloadClub();render();toast(clubState.outbox?'Some proposals still need delivery. Check Connections.':'Saved proposals delivered.');return true;}
 if(action==='club-discard'){modal('Discard unsent changes?',`<p>A separate recovery file will be kept. This stops retrying these proposals. Any proposal already received by the dealership computer stays in Review and must still be rejected there.</p>`,async()=>{await api('club','discard');await reloadClub();},'Back up & discard');return true;}
 if(action==='club-leave'){modal('Disconnect from this dealership?',`<p>A recovery backup will be saved. Your personal collection will become active. Unsent proposals must be delivered or explicitly discarded before leaving.</p>`,async()=>{await api('club','leave');switchCollection('local');await reloadClub();page='Connections';if(clubState.lastError)toast(clubState.lastError,true);},'Disconnect from dealership');return true;}
 if(action==='club-compare'){await clubComparison(id);return true;}
 return false;
}
